import{_ as n,l as t,o as e,c as s,v as o,p as l,x as r,d as E,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"董事会与监督","description":"","frontmatter":{"title":"董事会与监督","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/boards-monitoring.md","filePath":"econ/boards-monitoring.md","lastUpdated":1789023840000}'),p={name:"econ/boards-monitoring.md"};function h(m,a,A,B,_,u){const i=t("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="董事会与监督" tabindex="-1">董事会与监督 <a class="header-anchor" href="#董事会与监督" aria-label="Permalink to &quot;董事会与监督&quot;">​</a></h1><div class="epigraph"><p>董事会是股东的法定代理人，职责是聘经理、批重大决策、在危机里接手；它不是日常经营，监督强度取决于独立性、信息与谁真正选出董事。</p><footer>—— Hermalin and Weisbach, Endogenously Chosen Boards of Directors, American Economic Review 1998；Adams, Hermalin and Weisbach, The Role of Boards of Directors in Corporate Governance, Journal of Economic Literature 2010</footer></div><p><a href="/econ/creditor-coordination-empty-creditor">上一课</a>收束债权侧协调。主干<a href="/econ/control-rights">控制权</a>已把剩余权威定义为所有权。本课缺口是股权侧的常设机构：董事会如何监督经理，以及董事会本身被经理俘获的内生性。不重写 Aghion–Bolton 的状态转移，不把薪酬合同提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分散股东无法日日监测，把权威委给董事会。Hermalin–Weisbach：董事会独立性是内生的——表现好的经理讨价还价，董事会变弱，监督下降。Adams–Hermalin–Weisbach 综述：董事会同时顾问与监督，两者冲突（经理不愿向严监督者透露软信息）。缺口是：治理进阶从「谁有剩余控制权」推进到「这项权利如何被一个委员会行使」，以及独立性不是外生合规指标。</p><p><span class="marginnote">Tirole：监督是信息生产，与银行监测同构，对象换成经理的私人收益与努力。董事会比债权人更早介入，不必等到违约。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>功能：选聘/解聘 CEO、批准并购与资本结构、审计与合规。独立性：与经理无雇佣与家庭关系，降低俘获，也降低行业专用信息。双层结构（监事会/董事会）改变信息流，本课不做法系比较——那是 LLSV 课。交错董事会是反收购课的装置，这里只标：它同时保护监督者任期与经理壕沟。</p><p>内生：需要监督最强时（业绩差），经理对董事选任的影响力可能仍在，除非股权集中或控制权市场威胁。下一课薪酬、再下一课激进股东，是替代与互补的监督。</p>',9)),(e(),l(c,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E5%88%86%E6%95%A3%E8%82%A1%E4%B8%9C%22%5D%20--%3E%20BD%5B%22%E8%91%A3%E4%BA%8B%E4%BC%9A%22%5D%0A%20%20BD%20--%3E%20MON%5B%22%E7%9B%91%E7%9D%A3%3A%20%E8%A7%A3%E8%81%98%E4%B8%8E%E5%90%A6%E5%86%B3%22%5D%0A%20%20BD%20--%3E%20ADV%5B%22%E9%A1%BE%E9%97%AE%3A%20%E9%9C%80%E8%A6%81%E7%BB%8F%E7%90%86%E7%9A%84%E8%BD%AF%E4%BF%A1%E6%81%AF%22%5D%0A%20%20CEO%5B%22%E7%BB%8F%E7%90%86%E8%AE%AE%E4%BB%B7%22%5D%20--%3E%20END%5B%22%E7%8B%AC%E7%AB%8B%E6%80%A7%E5%86%85%E7%94%9F%22%5D%0A%20%20END%20--%3E%20WEAK%5B%22%E6%88%90%E5%8A%9F%E4%B9%8B%E5%90%8E%E7%9B%91%E7%9D%A3%E5%8F%98%E5%BC%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与债权：契约与银行是硬信息与违约触发；董事会管不可验证的战略。两者都弱时，靠接管市场（后课 Grossman–Hart）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是多层代理。股东→董事→经理。每一层都有信息与激励问题。董事要声誉与未来席位，可能讨好经理（谁提名）或讨好激进股东。独立性规则改变提名池，不自动改变目标函数。Hermalin–Weisbach 的要点：把独立性当因果变量做回归，会碰到内生——差公司才换独董，或强 CEO 不让换。</p><p>与 Jensen FCF：监督弱则现金浪费；董事会应决定派息与杠杆纪律。失败则把工作留给债务与收购。</p><h3 id="不是「独董比例越高越好」" tabindex="-1">不是「独董比例越高越好」 <a class="header-anchor" href="#不是「独董比例越高越好」" aria-label="Permalink to &quot;不是「独董比例越高越好」&quot;">​</a></h3><p>顾问功能需要知情。全独立且无行业知识的董事会，监督变成会计合规，战略捕获为零。最优不是角点。规模过大则搭便车，过小则技能不足。</p><p><span class="marginnote">本课对象是监督机制，不是交易所上市规则清单。合规可以是最低约束，经济学在内生议价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成董事责任判例。下一课：激励合同如何把可验证产出与薪酬挂钩，补董事会不可日日看见的努力。再后是外部股东压力。</p><p>后课默认：董事会是常设监督，独立性内生于经理议价；顾问与监督冲突。债权监督在违约之前较弱。治理单元从此按「谁说了算」递进。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>董事会代股东聘经理、否决重大决策；独立性内生于议价，不是外生常量。</li><li>监督与顾问冲突：严监测减少软信息。</li><li>与银行/契约监督分工：不可验证的战略靠董事会，可验证的靠债。</li><li>出处：Hermalin and Weisbach, <em>AER</em> 1998；Adams, Hermalin and Weisbach, <em>JEL</em> 2010。</li></ul>',12))])}const D=n(p,[["render",h]]);export{f as __pageData,D as default};
